add(6403376,"اسٹرابیری ماسکارپون پارفے",
"ماسکارپون اٹلی کا نرم کریم چیز ہے۔ یہ اتنا کریمی اور ملائم ہوتا ہے کہ ایک عام سی ترکیب میں گہرائی اور خاص ذائقہ پیدا کرنے کے لیے اس کی تھوڑی سی مقدار ہی کافی ہے۔ یہ پارفے ناشتے کے ساتھ پیش کرنے کے لیے کافی صحت بخش ہیں، یا میٹھے کے طور پر کافی لذیذ ہیں، اور صرف چند منٹ میں تیار ہو جاتے ہیں۔ اس ترکیب کو بہار اور گرمیوں کے لیے رکھ چھوڑیں، جب اسٹرابیری اپنے عروج پر ہوتی ہے۔",
"6","3/4 کپ",
["1 1/2 کپ اسٹرابیری (باریک کٹی ہوئی، تقسیم کر کے استعمال کریں)","3/4 اونس ماسکارپون چیز","1 کھانے کا چمچ چینی","1/2 کپ پورے السی کے بیج","1 چائے کا چمچ پسی ہوئی دار چینی","1 کپ ہلکا وینیلا دہی","3/4 کپ کم چکنائی والا بادام گرینولا"],
["1 کپ اسٹرابیری، ماسکارپون، چینی، السی اور دار چینی بلینڈر میں ڈال کر ہلکا ہونے تک پھینٹ لیں۔","دہی ملا لیں۔ 6 شفاف پارفے گلاسوں میں سے ہر ایک میں آمیزے کا 1/3 کپ ڈالیں۔ اس پر بچی ہوئی اسٹرابیری کے قتلوں کی ایک تہہ لگائیں (سجاوٹ کے لیے 6 قتلے الگ رکھ لیں)۔","ہر گلاس میں اسٹرابیری کے قتلوں پر 1 کھانے کا چمچ گرینولا چھڑکیں، پھر ہر گلاس میں اسٹرابیری کے بچے ہوئے آمیزے کی ایک اور تہہ لگائیں۔ ہر گلاس میں اسٹرابیری کے آمیزے کے اوپر 1 کھانے کا چمچ گرینولا کی ایک اور تہہ ڈالیں۔","ہر گلاس کو بچے ہوئے 1 اسٹرابیری کے قتلے سے سجائیں۔ پلاسٹک ریپ سے ڈھانپ دیں اور پیش کرنے سے پہلے کم از کم 2 گھنٹے اور زیادہ سے زیادہ رات بھر فریج میں رکھیں۔"])
add(6405391,"کرکرا پارمیزان چکن",
"یہ ترکیب پارمیزان چیز کے بھرپور ذائقے کے ساتھ مزیدار کرکری تہہ فراہم کرتی ہے۔ چکن کو اپنی پسندیدہ سائیڈ ڈشز کے ساتھ پیش کریں، جیسے بھنی ہوئی سبزیاں، سلاد، یا کم کاربوہائیڈریٹ والے سبزیوں کے نوڈلز آزمائیں۔",
"4","1 چکن بریسٹ",
["4 پورے بغیر ہڈی اور بغیر کھال کے چکن بریسٹ (تقریباً 4 اونس ہر ایک)","1/4 چائے کا چمچ کوشر نمک","1/2 چائے کا چمچ کالی مرچ","1/2 کپ میدہ","2 بڑے انڈوں کی سفیدی","1/3 کپ پارمیزان چیز (کم چکنائی والی)","1 چائے کا چمچ لہسن پاؤڈر","1 چائے کا چمچ خشک اوریگانو","1 چائے کا چمچ خشک تلسی","1/2 کپ بریڈ کرمبز (پورے گندم کے)","1 کھانے کا چمچ زیتون کا تیل"],
["اوون کو 400 ڈگری فارن ہائیٹ پر پہلے سے گرم کریں۔","چکن بریسٹ کے دونوں طرف کوشر نمک اور کالی مرچ لگائیں۔","میدہ ایک اتھلے پیالے میں ڈالیں۔","ایک الگ پیالے میں انڈے پھینٹ لیں۔","ایک اتھلی ڈش میں پارمیزان چیز، لہسن پاؤڈر، خشک اوریگانو، خشک تلسی اور بریڈ کرمبز ملا لیں۔","ہر چکن بریسٹ کو پہلے میدے میں، پھر انڈوں میں اور آخر میں پارمیزان کے آمیزے میں لپیٹیں، اور یکساں طور پر کوٹ کریں۔ اسے پلیٹ میں رکھیں اور باقی چکن بریسٹ کے ساتھ یہی عمل دہرائیں۔","اوون میں رکھنے کے قابل کڑاہی میں زیتون کا تیل درمیانی تیز آنچ پر گرم کریں۔","چکن بریسٹ کو کڑاہی میں ڈالیں اور ایک طرف سے 2–3 منٹ تک سنہری بھورا ہونے تک سیئر کریں۔","کڑاہی کو پہلے سے گرم اوون میں رکھیں اور تقریباً 15–18 منٹ تک بیک کریں، یا اس وقت تک جب تک چکن کا اندرونی درجہ حرارت 165 ڈگری فارن ہائیٹ تک نہ پہنچ جائے۔"])
